const grid=document.querySelector('#proposal-grid');
const dialog=document.querySelector('#proposal-dialog');
let previousFocus;
function render(filter='Todos'){
 const list=proposals.filter(p=>filter==='Todos'||p.topic===filter);
 grid.innerHTML=list.map(p=>`<article class="proposal"><div class="proposal-top"><span>${p.category}</span><span>${p.id} / 10</span></div><strong class="stat">${p.stat}</strong><p class="stat-label">${p.label}</p><h3>${p.title}</h3><button data-id="${p.id}" aria-label="Ver propuesta: ${p.title}">Conocé la propuesta <span aria-hidden="true">↗</span></button></article>`).join('');
 document.querySelector('#results').textContent=`${list.length} propuesta${list.length!==1?'s':''} para explorar`;
}
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});render(btn.dataset.filter);
}));
grid.addEventListener('click',event=>{
 const button=event.target.closest('[data-id]');if(!button)return;
 const p=proposals.find(item=>item.id===button.dataset.id);previousFocus=button;
 document.querySelector('#dialog-body').innerHTML=`<div class="section-label">PROPUESTA ${p.id} / 10 · ${p.category.toUpperCase()}</div><h2 id="dialog-title">${p.title}</h2><div class="dialog-stat"><strong>${p.stat}</strong><p>${p.label}</p></div><h3>EL PUNTO DE PARTIDA</h3><p>${p.problem}</p><h3>QUÉ PROPONEMOS</h3><ul>${p.actions.map(a=>`<li>${a}</li>`).join('')}</ul><p class="reference"><b>Referencia del documento:</b> ${p.source}${p.note?`<br><br>${p.note}`:''}<br><br><a href="https://canva.link/tnjabljx8lvlqqx" target="_blank" rel="noopener">Consultar presentación original ↗</a></p>`;
 dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');
});
function closeDialog(){dialog.close();}
document.querySelector('.close').addEventListener('click',closeDialog);
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');previousFocus?.focus();});
render();
